from fractions import Fraction
target_B = Fraction(2419, 2420)

def check_candidate_B():
    for n in range(1, 13):
        numerator_A = 12 + n
        numerator_B = 13 - n

        # Search for p and q up to a limit (300)
        limit = 300 

        for p in range(1, limit + 1):
            term_A = Fraction(numerator_A, p)

            if term_A >= target_B:
                continue

            remaining = target_B - term_A

            if remaining > 0:
                q_float = numerator_B / remaining

                # Check if q_float is an integer
                if abs(q_float - round(q_float)) < 1e-9:
                    q = int(round(q_float))

                    if q > 0 and q <= limit:
                        print(f"Found solution for B: n={n}, p={p}, q={q}")
                        return True
    return False

check_candidate_B()

